/**
 * ROI estimation. Every number the prospect eventually sees is computed here
 * from stated assumptions, never generated by a model. A model may estimate
 * "roughly 6 hours a week on manual scheduling"; the dollar figure is
 * arithmetic on top of that, and the assumptions ship alongside the result so
 * a reviewer — and later the prospect — can argue with the inputs.
 */

export interface RoiAssumptions {
  hourlyRateCents: number;
  weeksPerYear: number;
  /** Automation rarely eliminates a task outright. */
  automationEfficiency: number;
  /** Loaded cost multiplier over base wage: benefits, overhead, tooling. */
  loadedCostMultiplier: number;
}

export const DEFAULT_ASSUMPTIONS: RoiAssumptions = {
  hourlyRateCents: 3500,        // $35/hr — typical admin/coordinator wage
  weeksPerYear: 50,             // allows for two weeks of downtime
  automationEfficiency: 0.7,    // conservative: 70% of the identified time
  loadedCostMultiplier: 1.25,
};

export interface OpportunityEstimate {
  title: string;
  hoursPerWeek: number;
  confidence: number;
}

export interface RoiResult {
  hoursSavedPerMonth: number;
  annualSavingsCents: number;
  assumptions: RoiAssumptions & { note: string };
  perOpportunity: Array<{ title: string; hoursPerMonth: number; annualSavingsCents: number }>;
}

export function estimateRoi(
  opportunities: OpportunityEstimate[],
  overrides: Partial<RoiAssumptions> = {},
): RoiResult {
  const a = { ...DEFAULT_ASSUMPTIONS, ...overrides };
  const effectiveRate = a.hourlyRateCents * a.loadedCostMultiplier;

  const perOpportunity = opportunities.map((o) => {
    // Low-confidence opportunities are discounted rather than dropped, so a
    // speculative idea can't inflate the headline number.
    const realized = o.hoursPerWeek * a.automationEfficiency * Math.max(o.confidence, 0.4);
    return {
      title: o.title,
      hoursPerMonth: Math.round((realized * 52 / 12) * 10) / 10,
      annualSavingsCents: Math.round(realized * a.weeksPerYear * effectiveRate),
    };
  });

  return {
    hoursSavedPerMonth: Math.round(perOpportunity.reduce((s, o) => s + o.hoursPerMonth, 0)),
    annualSavingsCents: perOpportunity.reduce((s, o) => s + o.annualSavingsCents, 0),
    assumptions: {
      ...a,
      note: `Assumes $${(a.hourlyRateCents / 100).toFixed(0)}/hour loaded at ${a.loadedCostMultiplier}x, `
        + `${a.weeksPerYear} working weeks, and that automation removes ${Math.round(a.automationEfficiency * 100)}% `
        + `of the identified manual time. Estimates are discounted by research confidence.`,
    },
    perOpportunity,
  };
}
